CREATE TYPE "LotsStatuses" AS ENUM (
  'active',
  'finished'
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "lots" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar NOT NULL,
  "start_price" int NOT NULL CHECK (> 0),
  "current_price" int NOT NULL CHECK (>= start_price),
  "step" int NOT NULL CHECK (> 0),
  "ends_at" timestamptz NOT NULL CHECK (> created_at),
  "status" "LotsStatuses" NOT NULL DEFAULT 'active',
  "owner_id" int NOT NULL,
  "leader_id" int,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "bids" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "amount" int NOT NULL CHECK (> 0),
  "lot_id" int NOT NULL,
  "bidder_id" int NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE INDEX ON "lots" ("status", "ends_at");

CREATE INDEX ON "bids" ("lot_id", "created_at");

ALTER TABLE "lots" ADD FOREIGN KEY ("owner_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lots" ADD FOREIGN KEY ("leader_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bids" ADD FOREIGN KEY ("lot_id") REFERENCES "lots" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bids" ADD FOREIGN KEY ("bidder_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
